<script setup>
	async function getPhone(e){
		 // 用户拒绝授权
		  if (!e.detail.code) {
		    uni.showToast({title:'授权取消',icon:'none'})
		    return
			}
		// 1. 获取微信登录code
			let loginRes = await uni.login()
			let jsCode = loginRes.code
			
			console.log("aaaaaaaaaaaaaaaaaaa")
			console.log("<<<<"+jsCode+">>>>")
			
			// 2. 传给后端解密手机号登录
			  uni.request({
			    url: 'https://localhost:8080/api/wxPhoneLogin',
			    method: 'POST',
			    data: {
			      code: jsCode,
			      phoneCode: e.detail.code
			    },
			    success: res => {
			      if(res.data.code === 200){
			        // 登录成功存token
			        uni.setStorageSync('token',res.data.data.token)
			        uni.switchTab({url:'/pages/index/index'})
			      }else{
			        uni.showToast({title:res.data.msg,icon:'none'})
			      }
			    }
			  })
	}
	
	  

/* 子传父事件 */
const emit = defineEmits([
	'close',
	'success'
])

/* 关闭弹窗 */
